    with open('books.csv', newline='', encoding='utf-8') as csvfile:
        reader = csv.DictReader(csvfile)
        for row in reader:
            if row['genre'] == genre:
                titles.append(row['title'])
                # only need ratings for v2 mode
                ratings.append(float(row['rating']))

    if mode == 'v1':
        # Just return the list of matching titles
        return titles

    elif mode == 'v2':
        count = len(titles)
        avg_rating = float(sum(ratings) / count) if count > 0 else 0.0
        return {
            'titles': titles,
            'count': count,
            'avg_rating': avg_rating
        }

    elif mode == 'v3':
        count = len(titles)
        return {
            '@context': 'http://schema.org',
            '@type': 'BookCollection',
            'numberOfItems': count
        }

    else:
        # In case of unknown mode, default to v1
        return titles

